import subprocess, tempfile, json, os, shutil, sys
ORIG = '/workspace/executable'
def run(cmds, save=True, pre_open=None):
    d = tempfile.mkdtemp()
    args = [ORIG, 'run']
    for c in cmds:
        args += ['--cmd', c]
    if save:
        args += ['--save', 'x.bimcraft']
    p = subprocess.run(args, cwd=d, capture_output=True)
    out = p.stdout.decode().strip().split('\n')
    doc = None
    if save and os.path.exists(os.path.join(d, 'x.bimcraft')):
        doc = json.load(open(os.path.join(d, 'x.bimcraft')))
    shutil.rmtree(d)
    return out, p.stderr.decode(), doc
base_out, _, base = run([])
for code in sys.argv[1:]:
    out, err, doc = run(['standard {"set":"%s"}' % code])
    print('=====', code, err)
    reply = json.loads(out[0])
    reply.pop('all', None)
    print('reply:', json.dumps(reply, ensure_ascii=False))
    for k in doc:
        if k in ('uid', 'library', 'elements'):
            continue
        if k not in base:
            print('NEW', k, json.dumps(doc[k], ensure_ascii=False))
        elif doc[k] != base[k]:
            # show differing subkeys
            if isinstance(doc[k], dict):
                for kk in doc[k]:
                    if doc[k][kk] != base[k].get(kk):
                        print('CHANGED', k, kk, json.dumps(doc[k][kk], ensure_ascii=False)[:2000])
            else:
                print('CHANGED', k, json.dumps(doc[k], ensure_ascii=False)[:2000])
    print('top:', ','.join(doc.keys()))

