import subprocess, tempfile, json, os, shutil, sys, re
ORIG = '/workspace/executable'
def run(cmds, save=True):
    d = tempfile.mkdtemp()
    args = [ORIG, 'run']
    for c in cmds:
        args += ['--cmd', c]
    if save:
        args += ['--save', 'x.bimcraft']
    p = subprocess.run(args, cwd=d, capture_output=True)
    out = p.stdout.decode().strip().split('\n')
    doc = None
    if save and os.path.exists(os.path.join(d, 'x.bimcraft')):
        t = open(os.path.join(d, 'x.bimcraft')).read()
        m = {}
        def rep(mo):
            g = mo.group(0)
            if g not in m: m[g] = 'GUID-%d' % (len(m) + 1)
            return m[g]
        t = re.sub(r'[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}', rep, t)
        doc = json.loads(t)
    shutil.rmtree(d)
    return out, p.stderr.decode(), doc
# args: prefix commands separated by ';;' then the test command(s)
pre = [c for c in sys.argv[1].split(';;') if c.strip()] if len(sys.argv) > 1 else []
base_out, _, base = run(pre)
for test in sys.argv[2:]:
    cmds = pre + [c for c in test.split(';;') if c.strip()]
    out, err, doc = run(cmds)
    print('=====', test, err.strip())
    if doc is None:
        continue
    last = out[-2] if len(out) >= 2 else ''
    try:
        r = json.loads(last)
        if isinstance(r, dict):
            r.pop('all', None)
        print('reply:', json.dumps(r, ensure_ascii=False)[:300])
    except Exception:
        print('reply?', last[:300])
    for k in doc:
        if k in ('uid', 'library', 'elements'):
            continue
        if k not in base:
            print('NEW', k, json.dumps(doc[k], ensure_ascii=False)[:400])
        elif doc[k] != base[k]:
            print('CHANGED', k, json.dumps(doc[k], ensure_ascii=False)[:400])
    for k in base:
        if k not in doc:
            print('GONE', k)

