    p = subprocess.run([ORIG, 'run', '--cmd', 'units {"length":"ft-in"}', '--cmd', cmd], cwd=d, capture_output=True)
    shutil.rmtree(d)
    r = json.loads(p.stdout.decode().strip().split('\n')[-1])
    return {m['scale']: m['name'] for m in r['model']}
def nice(name):
    return not name.startswith('1 : ')
def thresh(n0, sign=1):
    # find delta where n0*(1+sign*delta) stops being nice; log-space bisection
    lo, hi = -14.0, -6.0   # log10 delta: lo nice, hi not nice
    for it in range(6):
        # evaluate 20 points in batch
        pts = [lo + (hi - lo) * i / 21 for i in range(1, 21)]
        sc = [n0 * (1 + sign * 10 ** p) for p in pts]
        res = names(sc)
        new_lo, new_hi = lo, hi
        for p, s in zip(pts, sc):
            nm = res.get(s)
            if nm is None:
                continue
            if nice(nm):
                new_lo = max(new_lo, p)
            else:
                new_hi = min(new_hi, p)
                break
        lo, hi = new_lo, new_hi
    return lo, hi
for n0 in [float(x) for x in sys.argv[1:]]:
    for sign in (1, -1):
        lo, hi = thresh(n0, sign)
        d = 10 ** ((lo + hi) / 2)
        n = n0 * (1 + sign * d)
        inches = 12 / n
        print('n0=%g sign=%d delta~%.4g  n=%r  inches diff=%.4g  64ths diff=%.4g  feet diff=%.4g' % (
            n0, sign, d, n, abs(inches - 12 / n0), abs(inches * 64 - 768 / n0), abs(n / 12 - n0 / 12)))

