import subprocess, tempfile, json, shutil, random
ORIG = '/workspace/executable'
MINE = '/tmp/styles-agent/settings/repo/target/release/bimcraft-cli'
W = [0.1, 0.13, 0.15, 0.18, 0.2, 0.22, 0.25, 0.28, 0.3, 0.35, 0.4, 0.5, 0.7, 1.0, 1.4, 2]
random.seed(7)
cands = set()
for q in range(1, 769):
    cands.add(768 / q)
for f in range(1, 400):
    cands.add(12.0 * f)
for i in range(300):
    cands.add(round(random.uniform(1, 2000), random.randint(0, 6)))
    cands.add(random.randint(1, 100000))
for q in range(1, 200):
    for eps in (1e-10, -1e-10, 5e-10, 2e-9):
        s = 768 / q * (1 + eps)
        if 1 <= s <= 100000:
            cands.add(s)
cands = sorted(c for c in cands if 1 <= c <= 100000)
def names(exe, scales, units):
    d = tempfile.mkdtemp()
    cmd = 'line_weights ' + json.dumps({"model": [{"scale": s, "widths": W} for s in scales]})
    p = subprocess.run([exe, 'run', '--cmd', 'units {"length":"%s"}' % units, '--cmd', cmd], cwd=d, capture_output=True)
    shutil.rmtree(d)
    r = json.loads(p.stdout.decode().strip().split('\n')[-1])
    return [(m['scale'], m['name']) for m in r['model']]
bad = 0
tot = 0
for units in ('ft-in', 'mm'):
    for i in range(0, len(cands), 32):
        chunk = cands[i:i + 32]
        a = names(ORIG, chunk, units)
        b = names(MINE, chunk, units)
        tot += len(a)
        for x, y in zip(a, b):
            if x != y:
                bad += 1
                if bad < 30:
                    print('DIFF', units, x, y)
print('%d of %d differ' % (bad, tot))

